@page "/contact"

<EditForm Model="Model" FormName="contact" Enhance OnValidSubmit="Send">
    <DataAnnotationsValidator />
    <InputText @bind-Value="Model!.Email" />
    <button type="submit">Send</button>
</EditForm>

@code {
    [SupplyParameterFromForm]
    private ContactModel? Model { get; set; }

    protected override void OnInitialized()
    {
        Model ??= new();
    }

    private void Send() { }
}

@page "/register"

<EditForm Model="model" OnValidSubmit="Register">
    <DataAnnotationsValidator />
    <ValidationSummary />

    <InputText @bind-Value="model.Email" />
    <InputText type="password" @bind-Value="model.Password" />
    <InputText type="password" @bind-Value="model.ConfirmPassword" />

    <button type="submit">Register</button>
</EditForm>

@code {
    private RegisterModel model = new();

    private void Register() { }

    public class RegisterModel
    {
        [Required, EmailAddress]
        public string? Email { get; set; }

        [Required, StringLength(100, MinimumLength = 8)]
        public string? Password { get; set; }

        [Compare(nameof(Password))]
        public string? ConfirmPassword { get; set; }
    }
}
